DELETE FROM `quest_template_locale` WHERE (`locale`='ptBR' AND `ID` IN (66695,66694,66661,66649,66648,66619,66618,65412,65411,54603,54484,54391,54388,54381,52438,50772,50647,49053,47007,41695,31528,8421));
INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(66695, 'ptBR', 'Destino Tentador: Sepulcro dos Primogênitos', '', '', '', '', '', '', '', '', 45114),
(66694, 'ptBR', 'Destino Tentador: Sacrário da Dominação', '', '', '', '', '', '', '', '', 45114),
(66661, 'ptBR', 'É só uma moeda, quanto pode custar?', 'Procure um Corretor em Oribos para obter informações.', '<Este objeto curioso traz mais perguntas que respostas. Como você o obteve? Para que serve? É perigoso?>\n\n<Se a Cidade Eterna não tiver respostas, com certeza os Corretores que negociam por lá terão.>', '', '', '', '', '', '', 45114),
(66649, 'ptBR', 'Virando a roda', 'Derrotar $1oa chefes de raides Fatídicos diferentes.', '<Ao longo das muitas provações, você sente o poder dentro de si crescer. Seja qual for a origem dessas anomalias, agora lhe trazem conforto, em vez de confusão.>\n\n<Mergulhe uma vez mais em incerteza, lute contra a escuridão e agarre o Destino com as duas mãos.>', '', '', '', '', '', '', 45114),
(66648, 'ptBR', 'Travessia fatídica', 'Derrote 30 chefes de raides Fatídicos diferentes.', '<A realidade gira ao seu redor. Suas lembranças deste lugar ficam obscurecidas e se movem intensamente a cada instante. Alguma coisa mudou.>\n\n<Você tem certeza de que, apesar de todas as semelhanças, este não é o lugar que você conhecia. Não exatamente.>\n\n<De qualquer forma, o caminho à frente chama. Nem enganação nem distorção vão atrasar seu destino.>', '', '', '', '', '', '', 45114),
(66619, 'ptBR', 'Antros', '', '', '', '', '', '', '', '', 45114),
(66618, 'ptBR', 'Mor\'geth', '', '', '', '', '', '', '', '', 45114),
(65412, 'ptBR', 'Juntando as peças', '', '', '', '', '', '', '', '', 45114),
(65411, 'ptBR', 'Situação de quebrar a cabeça', '', '', '', '', '', '', '', '', 45114),
(54603, 'ptBR', 'Feitor Krix', '', '', '', '', '', '', '', '', 45114),
(54484, 'ptBR', 'Treinamento sob medida', '', '', '', '', '', '', '', '', 45114),
(54391, 'ptBR', 'Doações da Costa Negra: Berilo Dourado Veloz', 'Colete $1oa Lombinhos Condimentados para Senedras no Porto de Boralus.', 'Uma bela e suculenta peça de carne será a refeição que os nossos aliados merecem antes de serem despachados para a batalha, sem falar que dá para fazer um bom ensopado com ela, coisa que os soldados curtem muito quando os ventos sopram e o frio da noite se espalha no ar.\n\nSe você me trouxer uns lombinhos condimentados frescos, eu os entregaria alegremente aos nossos oficiais intendentes.', '', '', '', '', '', '', 45114),
(54388, 'ptBR', 'Doações da Costa Negra: Capacete de Mergulho de Brilhescama', 'Colete $1oa Encantamento de Selo de Acerto Crítico - Anel para Mae Treme-varinha no Porto de Boralus.', '', '', '', '', '', '', '', 45114),
(54381, 'ptBR', 'Doações da Costa Negra: Tinta Ultramarina', 'Colete $1oa de Bagre Grelhado para Senedras no Porto de Boralus.', 'Saudações, viajante.\n\nRecebi a tarefa de garantir que os suprimentos alimentícios nunca faltem, e estamos ficando sem peixe ultimamente. Você gostaria de doar alguma coisa?', '', '', '', '', '', '', 45114),
(52438, 'ptBR', 'Uma jornada selvagem', 'Juntar-se à batalha no Rio Crenado.', 'Deixa eu te contar um negócio, sangue... isso aqui é trabalho de primeira!\n\nAgora que a máquina tá envenenada, não há tempo a perder.\n\nO pau tá quebrando no Rio Crenado. Leva o desordeiro tunado pro campo de batalha e cai matando!', '', '', '', '', '', '', 45114),
(50772, 'ptBR', 'À espreita', 'Encontre a Chefe Guerreira Sylvana Correventos na Costa Negra.', 'Está vendo todos esses fogos-fátuos? Já vi isso antes, quando o demônio Arquimonde caiu ante as ferroadas de centenas, digo, milhares de fogos-fátuos.\n\nIsso só pode querer dizer uma coisa. Malfurion está pedindo ajuda aos ancestrais.\n\nA Chefe Guerreira já levou um destacamento de batedores até a Costa Negra para interceptá-lo. Por favor, $n, encontre a Chefe Guerreira e veja se ela já capturou sua presa. \n\nNós já dominamos o Vale Gris, mas temos que continuar pressionando o inimigo.', '', '', '', '', '', '', 45114),
(50647, 'ptBR', 'Todo mundo tem um preço', 'Ajude Lorash a desarmar Astranaar.', 'Centenas de ladinos já atacaram os postos avançados kaldorei do Vale Gris. Ao meu sinal, eles iniciarão a próxima fase da guerra: semear o caos.\n\nMeu colega não morreu muito longe daqui, $n, você bem que podia me ajudar. Se ninguém nos vir, a cidade nem saberá que está sob ataque até termos apagado todos os guardas.\n\nEu tenho um veneno de efeito rápido e silencioso. Você sinaliza os alvos no ponto cego do inimigo e eu vou derrubando um por um.\n\nEntão, o que me diz?', '', '', '', '', '', '', 45114),
(49053, 'ptBR', 'Vigia', '', '', '', '', '', '', '', '', 45114),
(47007, 'ptBR', 'Dádiva da Torre dos Magos', '', '', '', '', '', '', '', '', 45114),
(41695, 'ptBR', 'PERIGO: Defília', '', '', '', '', '', '', '', '', 45114),
(31528, 'ptBR', 'Um desafio digno: Umbromestre Gandling', 'Completar o Modo Desafio de Scolomântia.', '$n, você tem de reunir um grupo destemido e liderá-lo pelas profundezas de Scolomântia. Lá dentro, ative o Orbe do Desafiante e elimine a presença má do Umbromestre Gandling.$B$BFale novamente comigo quando completar esse desafio, e eu $Go:a; recompensarei magnificamente.', '', '', '', '', '', '', 45114),
(8421, 'ptBR', 'The Wrong Stuff', 'Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood.', 'Now that I have my felcloth, I can really begin making *my* pet.$b$bIt\'s going to need some eyes though. Perhaps you could rip some rotting wood from the irontree folk for me, so I can carve out some lovely eyes. They\'re up north in the Irontree Woods.$b$bI\'ll also need some bloodvenom essence to give it that new demon smell. The tainted oozes carry the essence, and they hang out right here near Niby and me.', '', '', '', '', '', '', 45114);

